package dev.aeltorx.inflow.client;
import com.google.gson.*;
import dev.aeltorx.inflow.common.ProfileImageCodec;
import net.minecraft.client.Minecraft;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.Consumer;
import javax.imageio.ImageIO;

/** Authenticated server profiles. Images are a bounded session cache, not another local profile database. */
public final class SharedModeratorProfiles {
    private static final java.util.concurrent.ExecutorService IO=new java.util.concurrent.ThreadPoolExecutor(1,1,0,java.util.concurrent.TimeUnit.MILLISECONDS,new java.util.concurrent.ArrayBlockingQueue<>(16),r->{var t=new Thread(r,"inflow-profile-images");t.setDaemon(true);return t;},new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
    private record Job(String op,JsonObject q,Consumer<JsonObject> callback){}
    private static final ArrayDeque<Job> jobs=new ArrayDeque<>();private static Object connection;private static boolean sending,choosing;private static long revision;
    private static String selfAvatarKey="";private static final Map<String,BufferedImage> images=new LinkedHashMap<>();private static final Set<String> loading=new HashSet<>(),failed=new HashSet<>();
    public static void reset(){connection=Minecraft.getInstance().getConnection();jobs.clear();images.clear();loading.clear();failed.clear();sending=false;choosing=false;selfAvatarKey="";revision++;ModeratorAccount.useServerAvatar(null);}
    public static boolean supported(){return ModerationWorkspace.ready()&&ModerationWorkspace.summary.has("staffProfiles")&&ModerationWorkspace.summary.get("staffProfiles").getAsBoolean();}
    public static long revision(){return revision;}
    public static void retryImages(String uuid){failed.removeIf(key->key.startsWith(uuid+"/"));}
    public static boolean choosing(){return choosing;}
    public static void request(String op,JsonObject q,Consumer<JsonObject> callback){if(!supported()){var e=new JsonObject();e.addProperty("kind","error");e.addProperty("message","Общие профили требуют серверный InFlow 1.0.17");callback.accept(e);return;}if(jobs.size()>=24){var e=new JsonObject();e.addProperty("kind","error");e.addProperty("message","Очередь профилей занята");callback.accept(e);return;}jobs.add(new Job(op,q,callback));pump();}
    private static void pump(){if(sending||jobs.isEmpty())return;sending=true;Object session=Minecraft.getInstance().getConnection();var job=jobs.removeFirst();ModerationWorkspace.request(job.op,job.q,r->{if(session!=Minecraft.getInstance().getConnection())return;sending=false;try{job.callback.accept(r);}finally{pump();}});}
    public static JsonObject target(String uuid){var q=new JsonObject();q.addProperty("target",uuid);return q;}
    private static String key(JsonObject p,String kind){return p.get("uuid").getAsString()+"/"+kind+"/"+p.get(kind).getAsString();}
    public static BufferedImage image(JsonObject p,String kind){if(!p.has(kind)||p.get(kind).getAsString().isEmpty())return null;return images.get(key(p,kind));}
    public static void loadImages(JsonObject profile){if(profile.has("own")&&profile.get("own").getAsBoolean())selfAvatarKey=profile.has("avatar")&&!profile.get("avatar").getAsString().isEmpty()?key(profile,"avatar"):"";for(String kind:List.of("avatar","banner")){if(!profile.has(kind)||profile.get(kind).getAsString().isEmpty()){if(kind.equals("avatar")&&profile.has("own")&&profile.get("own").getAsBoolean())ModeratorAccount.useServerAvatar(null);continue;}String key=key(profile,kind);if(images.containsKey(key)){if(kind.equals("avatar")&&profile.get("own").getAsBoolean())ModeratorAccount.useServerAvatar(images.get(key));continue;}if(loading.contains(key)||failed.contains(key)||loading.size()>=4)continue;loading.add(key);download(profile.deepCopy(),kind,key,0,0,new ByteArrayOutputStream(),Minecraft.getInstance().getConnection());}}
    private static void download(JsonObject profile,String kind,String key,int offset,int expected,ByteArrayOutputStream output,Object session){if(session!=Minecraft.getInstance().getConnection())return;var q=target(profile.get("uuid").getAsString());q.addProperty("media",kind);q.addProperty("version",profile.get(kind).getAsString());q.addProperty("offset",offset);request("profile-media",q,r->{try{if(!r.get("kind").getAsString().equals("staff-media"))throw new IOException("Image unavailable");var d=r.getAsJsonObject("data");int size=d.get("size").getAsInt();byte[] part=Base64.getDecoder().decode(d.get("bytes").getAsString());if(size<1||size>ProfileImageCodec.MAX_STORED||expected!=0&&size!=expected||d.get("offset").getAsInt()!=offset||part.length<1||part.length>ProfileImageCodec.CHUNK||offset+part.length>size)throw new IOException("Invalid image chunk");output.writeBytes(part);if(output.size()<size){download(profile,kind,key,output.size(),size,output,session);return;}IO.execute(()->{try{byte[] checked=ProfileImageCodec.normalize(output.toByteArray(),kind);var image=ImageIO.read(new ByteArrayInputStream(checked));Minecraft.getInstance().execute(()->{if(session!=Minecraft.getInstance().getConnection())return;loading.remove(key);while(images.size()>=32)images.remove(images.keySet().iterator().next());images.put(key,image);revision++;if(kind.equals("avatar")&&profile.get("own").getAsBoolean()&&key.equals(selfAvatarKey))ModeratorAccount.useServerAvatar(image);});}catch(Exception e){Minecraft.getInstance().execute(()->{if(session==Minecraft.getInstance().getConnection()){loading.remove(key);if(failed.size()>=64)failed.clear();failed.add(key);}});}});}catch(Exception e){loading.remove(key);if(failed.size()>=64)failed.clear();failed.add(key);}});}
    public static void syncSelf(){var mc=Minecraft.getInstance();if(!supported()||mc.player==null)return;ModeratorAccount.ensure();request("profile-get",target(mc.player.getUUID().toString()),r->{if(r.get("kind").getAsString().equals("staff-profile"))loadImages(r.getAsJsonObject("data"));});}
    public static void choose(String kind,Consumer<String> status,Consumer<JsonObject> completed){if(choosing||!supported())return;choosing=true;var mc=Minecraft.getInstance();Object session=mc.getConnection();status.accept("Выбери PNG/JPEG — до 8 МиБ");IO.execute(()->{try(var stack=org.lwjgl.system.MemoryStack.stackPush()){var filters=stack.pointers(stack.UTF8("*.png"),stack.UTF8("*.jpg"),stack.UTF8("*.jpeg"));String selected=org.lwjgl.util.tinyfd.TinyFileDialogs.tinyfd_openFileDialog(kind.equals("avatar")?"Аватар профиля InFlow":"Баннер профиля InFlow","",filters,"PNG / JPEG",false);if(selected==null){mc.execute(()->{if(session==mc.getConnection()){choosing=false;status.accept("Выбор отменён");}});return;}Path source=Path.of(selected);if(!Files.isRegularFile(source)||Files.size(source)>ProfileImageCodec.MAX_SOURCE)throw new IOException("Изображение должно быть до 8 МиБ");byte[] sourceBytes;try(var input=Files.newInputStream(source)){sourceBytes=input.readNBytes(ProfileImageCodec.MAX_SOURCE+1);}byte[] bytes=ProfileImageCodec.normalize(sourceBytes,kind);mc.execute(()->{if(session!=mc.getConnection())return;status.accept("Загрузка на сервер…");var q=new JsonObject();q.addProperty("media",kind);q.addProperty("size",bytes.length);request("profile-image-start",q,r->{if(!r.get("kind").getAsString().equals("staff-media-ready")){choosing=false;completed.accept(r);return;}upload(bytes,0,r.getAsJsonObject("data").get("token").getAsString(),session,status,completed);});});}catch(Exception e){mc.execute(()->{if(session==mc.getConnection()){choosing=false;status.accept(e instanceof IOException?e.getMessage():"Не удалось прочитать изображение");}});}});}
    private static void upload(byte[] bytes,int offset,String token,Object session,Consumer<String> status,Consumer<JsonObject> completed){if(session!=Minecraft.getInstance().getConnection())return;int count=Math.min(ProfileImageCodec.CHUNK,bytes.length-offset);var q=new JsonObject();q.addProperty("token",token);q.addProperty("offset",offset);q.addProperty("bytes",Base64.getEncoder().encodeToString(Arrays.copyOfRange(bytes,offset,offset+count)));request("profile-image-chunk",q,r->{status.accept("Загрузка на сервер: "+(offset+count)*100/bytes.length+"%");if(r.get("kind").getAsString().equals("staff-media-next")&&offset+count<bytes.length)upload(bytes,offset+count,token,session,status,completed);else{choosing=false;completed.accept(r);}});}
}
